static inline void *kzalloc(size_t s, gfp_t gfp) /* <=== kzalloc */ 
{
	void *p = kmalloc(s, gfp);

	memset(p, 0, s);
	return p;
}

static inline void *kmalloc(size_t s, gfp_t gfp) /* <=== kmalloc */ 
{
	if (__kmalloc_fake)
		return __kmalloc_fake;
	return malloc(s);
}

static inline void dev_set_drvdata(struct device *dev, void *data) /* <=== dev_set_drvdata */ 
{
	dev->driver_data = data;
}

static inline void *kzalloc(size_t size, gfp_t flags) /* <=== kzalloc */ 
{
	return kmalloc(size, flags | __GFP_ZERO);
}

static inline void usb_set_serial_port_data(struct usb_serial_port *port, /* <=== usb_set_serial_port_data */ 
					    void *data)
{
	dev_set_drvdata(&port->dev, data);
}

